class MovieRentingSystem {
private:
    struct ShopMovie {
        int shop, movie;
        bool operator==(const ShopMovie& o) const { return shop == o.shop && movie == o.movie; }
    };
    struct ShopMovieHash {
        size_t operator()(const ShopMovie& sm) const { return hash<int>()(sm.shop) ^ (hash<int>()(sm.movie) << 16); }
    };
    unordered_map<ShopMovie, int, ShopMovieHash> priceMap;
    unordered_map<int, set<pair<int, int>>> unrented;
    set<tuple<int, int, int>> rented;
public:
    MovieRentingSystem(int n, vector<vector<int>>& entries) {
        for (const auto& e : entries) {
            int shop = e[0], movie = e[1], price = e[2];
            priceMap[{shop, movie}] = price;
            unrented[movie].insert({price, shop});
        }
    }

    vector<int> search(int movie) {
        vector<int> res;
        auto it = unrented.find(movie);
        if (it == unrented.end()) return res;
        int count = 0;
        for (const auto& p : it->second) {
            res.push_back(p.second);
            if (++count == 5) break;
        }
        return res;
    }

    void rent(int shop, int movie) {
        int price = priceMap[{shop, movie}];
        unrented[movie].erase({price, shop});
        rented.insert({price, shop, movie});
    }

    void drop(int shop, int movie) {
        int price = priceMap[{shop, movie}];
        rented.erase({price, shop, movie});
        unrented[movie].insert({price, shop});
    }

    vector<vector<int>> report() {
        vector<vector<int>> res;
        int count = 0;
        for (const auto& t : rented) {
            res.push_back({get<1>(t), get<2>(t)});
            if (++count == 5) break;
        }
        return res;
    }
};

class MovieRentingSystem {
    private Map<String, Integer> priceMap = new HashMap<>();
    private Map<Integer, TreeSet<int[]>> unrented = new HashMap<>();
    private TreeSet<int[]> rented = new TreeSet<>((a, b) -> {
        if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
        if (a[1] != b[1]) return Integer.compare(a[1], b[1]);
        return Integer.compare(a[2], b[2]);
    });

    public MovieRentingSystem(int n, int[][] entries) {
        for (int[] e : entries) {
            int shop = e[0], movie = e[1], price = e[2];
            priceMap.put(shop + "," + movie, price);
            unrented.computeIfAbsent(movie, k -> new TreeSet<>((a, b) -> {
                if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
                return Integer.compare(a[1], b[1]);
            })).add(new int[]{price, shop});
        }
    }

    public List<Integer> search(int movie) {
        List<Integer> res = new ArrayList<>();
        TreeSet<int[]> set = unrented.get(movie);
        if (set == null) return res;
        int count = 0;
        for (int[] p : set) {
            res.add(p[1]);
            if (++count == 5) break;
        }
        return res;
    }

    public void rent(int shop, int movie) {
        int price = priceMap.get(shop + "," + movie);
        unrented.get(movie).remove(new int[]{price, shop});
        rented.add(new int[]{price, shop, movie});
    }

    public void drop(int shop, int movie) {
        int price = priceMap.get(shop + "," + movie);
        rented.remove(new int[]{price, shop, movie});
        unrented.get(movie).add(new int[]{price, shop});
    }

    public List<List<Integer>> report() {
        List<List<Integer>> res = new ArrayList<>();
        int count = 0;
        for (int[] item : rented) {
            res.add(Arrays.asList(item[1], item[2]));
            if (++count == 5) break;
        }
        return res;
    }
}

class MovieRentingSystem {
  constructor(n, entries) {
    this.priceMap = new Map();
    this.unrented = new Map();
    this.rented = [];
    for (const [shop, movie, price] of entries) {
      this.priceMap.set(`${shop},${movie}`, price);
      if (!this.unrented.has(movie)) {
        this.unrented.set(movie, []);
      }
      this.unrented.get(movie).push({ price, shop });
    }
    for (const list of this.unrented.values()) {
      list.sort((a, b) => a.price - b.price || a.shop - b.shop);
    }
  }

  search(movie) {
    const list = this.unrented.get(movie);
    if (!list) return [];
    return list.slice(0, 5).map(x => x.shop);
  }

  rent(shop, movie) {
    const price = this.priceMap.get(`${shop},${movie}`);
    const list = this.unrented.get(movie);
    const idx = list.findIndex(x => x.shop === shop && x.price === price);
    if (idx !== -1) list.splice(idx, 1);
    this.rented.push({ price, shop, movie });
    this.rented.sort((a, b) => a.price - b.price || a.shop - b.shop || a.movie - b.movie);
  }

  drop(shop, movie) {
    const price = this.priceMap.get(`${shop},${movie}`);
    const idx = this.rented.findIndex(x => x.shop === shop && x.movie === movie);
    if (idx !== -1) this.rented.splice(idx, 1);
    const list = this.unrented.get(movie);
    list.push({ price, shop });
    list.sort((a, b) => a.price - b.price || a.shop - b.shop);
  }

  report() {
    return this.rented.slice(0, 5).map(x => [x.shop, x.movie]);
  }
}
